INSERT INTO notification_templates (channel, template_key, locale, subject, body) VALUES
('EMAIL', 'ORDER_CONFIRMED', 'vi', 'Đơn #{{order_no}} đã được đặt thành công', '<h2 style="margin:0 0 6px;font-size:18px">Cảm ơn bạn đã đặt hàng!</h2><p style="margin:0">Đơn <b>#{{order_no}}</b> · đặt lúc {{placed_at}}</p><p>Shop sẽ gọi điện xác nhận trong vòng 24 giờ.</p>{{>order_items}}{{>order_totals}}<p style="font-size:13px"><b>{{labels.ship_to}}:</b> {{ship_to.name}} · {{ship_to.phone_masked}}<br>{{ship_to.address}}</p>{{>order_button}}'),
('EMAIL', 'ORDER_CONFIRMED', 'en', 'Order #{{order_no}} received', '<h2 style="margin:0 0 6px;font-size:18px">Thank you for your order!</h2><p style="margin:0">Order <b>#{{order_no}}</b> · placed {{placed_at}}</p><p>The shop will call you to confirm within 24 hours.</p>{{>order_items}}{{>order_totals}}<p style="font-size:13px"><b>{{labels.ship_to}}:</b> {{ship_to.name}} · {{ship_to.phone_masked}}<br>{{ship_to.address}}</p>{{>order_button}}'),
('EMAIL', 'ORDER_PREPARING', 'vi', 'Đơn #{{order_no}} đang được chuẩn bị', '<h2 style="margin:0 0 6px;font-size:18px">Shop đã xác nhận đơn của bạn</h2><p style="margin:0">Đơn <b>#{{order_no}}</b> · đặt lúc {{placed_at}}</p><p>Đơn hàng đang được chuẩn bị.</p>{{>order_items}}{{>order_button}}'),
('EMAIL', 'ORDER_PREPARING', 'en', 'Order #{{order_no}} is being prepared', '<h2 style="margin:0 0 6px;font-size:18px">The shop has confirmed your order</h2><p style="margin:0">Order <b>#{{order_no}}</b> · placed {{placed_at}}</p><p>Your order is being prepared.</p>{{>order_items}}{{>order_button}}'),
('EMAIL', 'ORDER_DELIVERED', 'vi', 'Đơn #{{order_no}} đã giao thành công', '<h2 style="margin:0 0 6px;font-size:18px">Giao hàng thành công</h2><p style="margin:0">Đơn <b>#{{order_no}}</b> · đặt lúc {{placed_at}}</p><p>Đơn hàng đã được giao. Cảm ơn bạn đã mua sắm!</p>{{>order_items}}{{>order_button}}'),
('EMAIL', 'ORDER_DELIVERED', 'en', 'Order #{{order_no}} has been delivered', '<h2 style="margin:0 0 6px;font-size:18px">Delivered</h2><p style="margin:0">Order <b>#{{order_no}}</b> · placed {{placed_at}}</p><p>Your order has been delivered. Thank you for shopping with us!</p>{{>order_items}}{{>order_button}}'),
('EMAIL', 'ORDER_CANCELLED', 'vi', 'Đơn #{{order_no}} đã bị hủy', '<h2 style="margin:0 0 6px;font-size:18px">Đơn hàng đã bị hủy</h2><p style="margin:0">Đơn <b>#{{order_no}}</b> · đặt lúc {{placed_at}}</p><p>{{cancel_reason}}</p><p>Bạn chưa thanh toán nên không có khoản tiền nào cần hoàn.</p>{{>order_items}}{{>order_button}}'),
('EMAIL', 'ORDER_CANCELLED', 'en', 'Order #{{order_no}} was cancelled', '<h2 style="margin:0 0 6px;font-size:18px">Your order was cancelled</h2><p style="margin:0">Order <b>#{{order_no}}</b> · placed {{placed_at}}</p><p>{{cancel_reason}}</p><p>You have not paid, so there is nothing to refund.</p>{{>order_items}}{{>order_button}}'),
('EMAIL', 'ORDER_RETURNED', 'vi', 'Đơn #{{order_no}} đã hoàn về shop', '<h2 style="margin:0 0 6px;font-size:18px">Đơn hàng đã hoàn về shop</h2><p style="margin:0">Đơn <b>#{{order_no}}</b> · đặt lúc {{placed_at}}</p><p>Bạn chưa thanh toán nên không có khoản tiền nào cần hoàn.</p>{{>order_items}}{{>order_button}}'),
('EMAIL', 'ORDER_RETURNED', 'en', 'Order #{{order_no}} returned to the shop', '<h2 style="margin:0 0 6px;font-size:18px">Your order was returned to the shop</h2><p style="margin:0">Order <b>#{{order_no}}</b> · placed {{placed_at}}</p><p>You have not paid, so there is nothing to refund.</p>{{>order_items}}{{>order_button}}'),
('EMAIL', 'RESET_PASSWORD', 'vi', 'Đặt lại mật khẩu', '<h2 style="margin:0 0 6px;font-size:18px">Đặt lại mật khẩu</h2><p>Bạn vừa yêu cầu đặt lại mật khẩu. Link có hiệu lực 30 phút.</p><p style="text-align:center;margin:18px 0 4px"><a href="@@RESET_URL@@" style="display:inline-block;background:#222;color:#fff;padding:10px 22px;font-size:13px;font-weight:bold;text-decoration:none">ĐẶT LẠI MẬT KHẨU</a></p><p style="color:#777;font-size:12px">Nếu không phải bạn, hãy bỏ qua email này.</p>'),
('EMAIL', 'RESET_PASSWORD', 'en', 'Reset your password', '<h2 style="margin:0 0 6px;font-size:18px">Reset your password</h2><p>You asked to reset your password. The link is valid for 30 minutes.</p><p style="text-align:center;margin:18px 0 4px"><a href="@@RESET_URL@@" style="display:inline-block;background:#222;color:#fff;padding:10px 22px;font-size:13px;font-weight:bold;text-decoration:none">RESET PASSWORD</a></p><p style="color:#777;font-size:12px">If this was not you, ignore this email.</p>');
